
% Generated by CE-planner for the private mult5zsic_ce.pl copy.
% Goal-preservation predicates are always emitted; exact-world
% predicates are emitted when sampled-world preservation is enabled.
% No option/1 clause is appended here: the private copy
% is patched at the original option declaration, avoiding ambiguous
% SICStus clause-loading order.
ce_planner_literal_atom(neg(X), X) :- !.
ce_planner_literal_atom(X, X).

ce_planner_project_world([], _, []).
ce_planner_project_world([L|Ls], Fluents, [L|Ps]) :-
    ce_planner_literal_atom(L, A), member(A, Fluents), !,
    ce_planner_project_world(Ls, Fluents, Ps).
ce_planner_project_world([_|Ls], Fluents, Ps) :-
    ce_planner_project_world(Ls, Fluents, Ps).

ce_planner_wrap_literal_worlds([], []).
ce_planner_wrap_literal_worlds([L|Ls], [[L]|Ws]) :-
    ce_planner_wrap_literal_worlds(Ls, Ws).

ce_planner_normalize_worlds([], []).
ce_planner_normalize_worlds([H|T], Worlds) :-
    ( H = [_|_] -> Worlds = [H|T]
    ; ce_planner_wrap_literal_worlds([H|T], Worlds) ).

ce_planner_project_worlds([], _, []).
ce_planner_project_worlds([W|Ws], Fluents, [P|Ps]) :-
    ce_planner_project_world(W, Fluents, P),
    ce_planner_project_worlds(Ws, Fluents, Ps).

ce_planner_world_atom_set(World, Atoms) :-
    findall(A, (member(L, World), ce_planner_literal_atom(L, A)), Raw),
    sort(Raw, Atoms), length(Raw, N), length(Atoms, N).

ce_planner_validate_projected_worlds([]).
ce_planner_validate_projected_worlds([W|Ws]) :-
    ce_planner_world_atom_set(W, Atoms),
    ce_planner_validate_projected_worlds_rest(Ws, Atoms).
ce_planner_validate_projected_worlds_rest([], _).
ce_planner_validate_projected_worlds_rest([W|Ws], Atoms) :-
    ce_planner_world_atom_set(W, Atoms),
    ce_planner_validate_projected_worlds_rest(Ws, Atoms).

ce_planner_collect_exact_worlds([], []).
ce_planner_collect_exact_worlds([G], Worlds) :- !,
    ce_planner_normalize_worlds(G, Worlds).
ce_planner_collect_exact_worlds(_, _) :-
    format(user_error,
      'CE-PLANNER ERROR: expected at most one sampled-world ONEOF~n', []),
    fail.

ce_planner_dump_exact_world_oneof(Fluents) :-
    findall(G, cpa_initially(cpa_oneof(G)), Groups),
    ce_planner_collect_exact_worlds(Groups, Worlds0),
    ce_planner_project_worlds(Worlds0, Fluents, Projected0),
    ( ce_planner_validate_projected_worlds(Projected0) -> true
    ; format(user_error,
        'CE-PLANNER ERROR: sampled worlds are incomplete or contradictory after projection~n', []),
      fail ),
    sort(Projected0, Projected),
    length(Projected, WorldCount), length(Fluents, FluentCount),
    format('%% CE-planner exact sampled worlds: ~q; projected fluents: ~q~n',
           [WorldCount, FluentCount]),
    ce_planner_dump_projected_worlds(Projected).

ce_planner_dump_projected_worlds([]).
ce_planner_dump_projected_worlds([[]]) :- !.
ce_planner_dump_projected_worlds([W]) :- !,
    ce_planner_dump_world_units(W).
ce_planner_dump_projected_worlds(Ws) :-
    format('initially ', []),
    ce_planner_dump_world_disjunction(Ws),
    format(';~n', []).

ce_planner_dump_world_units([]).
ce_planner_dump_world_units([L|Ls]) :-
    format('initially ', []),
    ce_planner_dump_literal(L),
    format(';~n', []),
    ce_planner_dump_world_units(Ls).

ce_planner_dump_world_disjunction([W]) :- !,
    ce_planner_dump_world(W).
ce_planner_dump_world_disjunction([W|Ws]) :-
    ce_planner_dump_world(W), format(' | ', []),
    ce_planner_dump_world_disjunction(Ws).

ce_planner_dump_world(W) :-
    format('(', []), ce_planner_dump_literals(W), format(')', []).

ce_planner_dump_literals([]).
ce_planner_dump_literals([L]) :- !, ce_planner_dump_literal(L).
ce_planner_dump_literals([L|Ls]) :-
    ce_planner_dump_literal(L), format(',', []),
    ce_planner_dump_literals(Ls).

ce_planner_dump_literal(neg(X)) :- !, format('-~q', [X]).
ce_planner_dump_literal(X) :- format('~q', [X]).

% Keep the complete PDDL goal in one AL theory.  pddl2pl emits
% each top-level conjunction member as a separate plan_goal/1 fact;
% nested OR/AND formulae remain cpa_or/cpa_and terms.  Multiple goal
% statements in one CPAH theory are conjunctive, while alternatives
% inside one statement are disjunctive.
ce_planner_dump_all_goals :-
    findall(G, plan_goal(G), Goals),
    Goals \= [],
    ce_planner_dump_goal_terms(Goals).
ce_planner_dump_goal_terms([]).
ce_planner_dump_goal_terms([G|Gs]) :-
    findall(C, cv_and(G,C), Alternatives),
    Alternatives \= [],
    dump_one_goal(Alternatives),
    ce_planner_dump_goal_terms(Gs).
